#!/usr/bin/env bash
# Generates every richimg APNG test fixture and its reference frames, so
# `cargo test -p richimg` needs no image tool at run time (only at fixture
# generation time, i.e. when this script is re-run after a deliberate
# change). Re-running it is idempotent: it recreates every generated file
# from scratch in a throwaway temp directory and only then copies the
# results over the committed ones. Sibling of `make.sh` (WebP); this one
# owns `tests/fixtures/apng/**` only and never touches `make.sh`'s files.
#
# Every APNG fixture is hand-assembled byte-for-byte in python3 (struct +
# zlib + crc32): real encoders (`ffmpeg -f apng`, `magick`) choose their own
# dispose/blend ops and never emit a "default image that is not a frame", so
# there is no tool that can produce the specific `fcTL` fields these tests
# need to pin. References are raw RGBA8 from ffmpeg's own (independent)
# APNG decoder, which composites internally before the `rawvideo` mux —
# never generated by richimg's own code.
set -euo pipefail

FIXTURES_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/apng"
REFS_DIR="$FIXTURES_DIR/refs"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

mkdir -p "$FIXTURES_DIR" "$REFS_DIR"
cd "$WORK"

# ---------------------------------------------------------------------------
# The APNG builder. Every fixture below is a call into this module: it
# hand-assembles PNG chunks (IHDR/PLTE/tRNS/acTL/fcTL/IDAT/fdAT/IEND) with
# real CRC32s, giving exact control over every `fcTL` field that no encoder
# exposes (sequence numbers, a leading `fcTL`-less default image, dispose ops
# per frame, etc).
# ---------------------------------------------------------------------------
cat > apnglib.py <<'PY'
import struct
import zlib

PNG_SIGNATURE = bytes([137, 80, 78, 71, 13, 10, 26, 10])

# APNG spec dispose/blend op codes (https://wiki.mozilla.org/APNG_Specification).
DISPOSE_NONE, DISPOSE_BACKGROUND, DISPOSE_PREVIOUS = 0, 1, 2
BLEND_SOURCE, BLEND_OVER = 0, 1

# PNG IHDR color types.
COLOR_GRAYSCALE, COLOR_RGB, COLOR_INDEXED, COLOR_GRAYSCALE_ALPHA, COLOR_RGBA = 0, 2, 3, 4, 6


def chunk(tag, data):
    body = tag + data
    return struct.pack(">I", len(data)) + body + struct.pack(">I", zlib.crc32(body) & 0xFFFFFFFF)


def ihdr(width, height, bit_depth, color_type):
    return chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, bit_depth, color_type, 0, 0, 0))


def plte(entries):
    """`entries`: list of (r, g, b)."""
    return chunk(b"PLTE", b"".join(struct.pack(">BBB", r, g, b) for r, g, b in entries))


def trns(alphas):
    """`alphas`: list of per-palette-entry alpha bytes."""
    return chunk(b"tRNS", bytes(alphas))


def actl(num_frames, num_plays):
    return chunk(b"acTL", struct.pack(">II", num_frames, num_plays))


def fctl(seq, width, height, x_offset, y_offset, delay_num, delay_den, dispose_op, blend_op):
    return chunk(
        b"fcTL",
        struct.pack(
            ">IIIIIHHBB",
            seq, width, height, x_offset, y_offset, delay_num, delay_den, dispose_op, blend_op,
        ),
    )


def idat(scanlines):
    return chunk(b"IDAT", zlib.compress(scanlines, 9))


def fdat(seq, scanlines):
    return chunk(b"fdAT", struct.pack(">I", seq) + zlib.compress(scanlines, 9))


def iend():
    return chunk(b"IEND", b"")


def scanlines_rgba8(pixels, width, height):
    """`pixels`: row-major list of (r, g, b, a), filter type None on every row."""
    out = bytearray()
    for y in range(height):
        out.append(0)
        for x in range(width):
            r, g, b, a = pixels[y * width + x]
            out += bytes([r, g, b, a])
    return bytes(out)


def scanlines_rgb8(pixels, width, height):
    out = bytearray()
    for y in range(height):
        out.append(0)
        for x in range(width):
            r, g, b = pixels[y * width + x]
            out += bytes([r, g, b])
    return bytes(out)


def scanlines_rgba16(pixels, width, height):
    """`pixels`: row-major list of (r, g, b, a) 16-bit big-endian values."""
    out = bytearray()
    for y in range(height):
        out.append(0)
        for x in range(width):
            r, g, b, a = pixels[y * width + x]
            out += struct.pack(">HHHH", r, g, b, a)
    return bytes(out)


def scanlines_indexed8(indices, width, height):
    out = bytearray()
    for y in range(height):
        out.append(0)
        for x in range(width):
            out.append(indices[y * width + x])
    return bytes(out)


def solid(width, height, pixel):
    return [pixel] * (width * height)


class ApngBuilder:
    """Assembles one APNG file from a sequence of frames, plus an optional
    leading default image that is NOT part of the animation (no `fcTL`
    before `IDAT`)."""

    def __init__(self, width, height, bit_depth=8, color_type=COLOR_RGBA, palette=None, trns_alphas=None):
        self.width = width
        self.height = height
        self.bit_depth = bit_depth
        self.color_type = color_type
        self.palette = palette
        self.trns_alphas = trns_alphas
        self.seq = 0

    def _next_seq(self):
        value = self.seq
        self.seq += 1
        return value

    def build(self, frames, default_image_scanlines=None, num_plays=1):
        """`frames`: list of dicts with keys width, height, x_offset, y_offset,
        delay_num, delay_den, dispose_op, blend_op, scanlines.
        `default_image_scanlines`: if given, becomes the `IDAT` payload with
        NO preceding `fcTL` (a non-animated default image); frame 0's own
        `fcTL`+`fdAT` follow. If omitted, frame 0's `fcTL` precedes `IDAT`
        (`IDAT` itself is frame 0).
        """
        out = bytearray()
        out += PNG_SIGNATURE
        out += ihdr(self.width, self.height, self.bit_depth, self.color_type)
        if self.palette is not None:
            out += plte(self.palette)
        if self.trns_alphas is not None:
            out += trns(self.trns_alphas)
        out += actl(len(frames), num_plays)

        if default_image_scanlines is not None:
            out += idat(default_image_scanlines)
            for frame in frames:
                out += fctl(
                    self._next_seq(), frame["width"], frame["height"], frame["x_offset"], frame["y_offset"],
                    frame["delay_num"], frame["delay_den"], frame["dispose_op"], frame["blend_op"],
                )
                out += fdat(self._next_seq(), frame["scanlines"])
        else:
            first = frames[0]
            out += fctl(
                self._next_seq(), first["width"], first["height"], first["x_offset"], first["y_offset"],
                first["delay_num"], first["delay_den"], first["dispose_op"], first["blend_op"],
            )
            out += idat(first["scanlines"])
            for frame in frames[1:]:
                out += fctl(
                    self._next_seq(), frame["width"], frame["height"], frame["x_offset"], frame["y_offset"],
                    frame["delay_num"], frame["delay_den"], frame["dispose_op"], frame["blend_op"],
                )
                out += fdat(self._next_seq(), frame["scanlines"])

        out += iend()
        return bytes(out)


def frame(width, height, x_offset, y_offset, pixels, delay_num=1, delay_den=10,
          dispose_op=DISPOSE_NONE, blend_op=BLEND_SOURCE, encode=scanlines_rgba8):
    return {
        "width": width, "height": height, "x_offset": x_offset, "y_offset": y_offset,
        "delay_num": delay_num, "delay_den": delay_den, "dispose_op": dispose_op, "blend_op": blend_op,
        "scanlines": encode(pixels, width, height),
    }
PY

# ---------------------------------------------------------------------------
# 1: dispose = NONE, three full/partial frames accumulating on the canvas —
# proves NONE leaves everything drawn so far in place (contrast with the
# BACKGROUND fixture below).
# ---------------------------------------------------------------------------
python3 - <<'PY'
import sys
sys.path.insert(0, ".")
from apnglib import *

W = H = 4
b = ApngBuilder(W, H)
frames = [
    frame(W, H, 0, 0, solid(W, H, (255, 0, 0, 255))),
    frame(2, 2, 0, 0, solid(2, 2, (0, 255, 0, 255))),          # top-left
    frame(2, 2, 2, 2, solid(2, 2, (0, 0, 255, 255))),          # bottom-right, opposite corner
]
open("dispose_none.png", "wb").write(b.build(frames))
PY

# ---------------------------------------------------------------------------
# 2: dispose = BACKGROUND. Frame 0 is full-canvas opaque red with
# dispose=Background; frame 1 covers only the left half, so the right half
# must come out transparent (frame 0's region was cleared before frame 1
# drew), never red.
# ---------------------------------------------------------------------------
python3 - <<'PY'
import sys
sys.path.insert(0, ".")
from apnglib import *

W, H = 4, 2
b = ApngBuilder(W, H)
frames = [
    frame(W, H, 0, 0, solid(W, H, (255, 0, 0, 255)), dispose_op=DISPOSE_BACKGROUND),
    frame(2, H, 0, 0, solid(2, H, (0, 255, 0, 255))),
]
open("dispose_background.png", "wb").write(b.build(frames))
PY

# ---------------------------------------------------------------------------
# 3: dispose = PREVIOUS (not on frame 0). Frame 0 establishes a blue
# background (dispose=None). Frame 1 (dispose=Previous) draws green over the
# whole canvas. Frame 2 draws fully-transparent pixels with blend=Over (a
# no-op blend), so what shows must be frame 1's disposal restoring frame 0's
# blue — never green, and never a BACKGROUND-style clear to transparent.
# ---------------------------------------------------------------------------
python3 - <<'PY'
import sys
sys.path.insert(0, ".")
from apnglib import *

W = H = 4
b = ApngBuilder(W, H)
frames = [
    frame(W, H, 0, 0, solid(W, H, (0, 0, 255, 255))),
    frame(W, H, 0, 0, solid(W, H, (0, 255, 0, 255)), dispose_op=DISPOSE_PREVIOUS),
    frame(W, H, 0, 0, solid(W, H, (0, 0, 0, 0)), blend_op=BLEND_OVER),
]
open("dispose_previous.png", "wb").write(b.build(frames))
PY

# ---------------------------------------------------------------------------
# 4: dispose = PREVIOUS on FRAME 0 specifically. Per the APNG spec this is
# treated as BACKGROUND (there is no prior state), so frame 0's region clears
# to transparent before frame 1 — not "no-op" (which PREVIOUS would otherwise
# be read as, restoring an undefined earlier state).
# ---------------------------------------------------------------------------
python3 - <<'PY'
import sys
sys.path.insert(0, ".")
from apnglib import *

W = H = 4
b = ApngBuilder(W, H)
frames = [
    frame(W, H, 0, 0, solid(W, H, (255, 0, 0, 255)), dispose_op=DISPOSE_PREVIOUS),
    frame(W, H, 0, 0, solid(W, H, (0, 0, 0, 0)), blend_op=BLEND_OVER),
]
open("dispose_previous_first_frame.png", "wb").write(b.build(frames))
PY

