# ---------------------------------------------------------------------------
# 10: a default image that is NOT a frame (no `fcTL` before `IDAT`). The
# default image is a distinctive magenta that must never appear in any
# decoded frame; `frame_count` must be 2 (acTL.num_frames), not 3.
# ---------------------------------------------------------------------------
python3 - <<'PY'
import sys
sys.path.insert(0, ".")
from apnglib import *

W = H = 4
b = ApngBuilder(W, H)
default_image = scanlines_rgba8(solid(W, H, (255, 0, 255, 255)), W, H)  # distinctive magenta
frames = [
    frame(W, H, 0, 0, solid(W, H, (255, 0, 0, 255))),
    frame(W, H, 0, 0, solid(W, H, (0, 255, 0, 255))),
]
open("default_image_not_a_frame.png", "wb").write(b.build(frames, default_image_scanlines=default_image))
