# ---------------------------------------------------------------------------
# 11: palette + tRNS. Two palette entries, one of them partially transparent,
# so EXPAND+ALPHA must turn indices into straight-alpha RGBA8.
# ---------------------------------------------------------------------------
python3 - <<'PY'
import sys
sys.path.insert(0, ".")
from apnglib import *

W = H = 2
palette = [(200, 20, 20), (20, 200, 20)]
alphas = [255, 100]  # index 0 opaque, index 1 semi-transparent
b = ApngBuilder(W, H, bit_depth=8, color_type=COLOR_INDEXED, palette=palette, trns_alphas=alphas)
frame0 = frame(W, H, 0, 0, [0, 1, 1, 0], encode=lambda idx, w, h: scanlines_indexed8(idx, w, h))
frame1 = frame(W, H, 0, 0, [1, 0, 0, 1], encode=lambda idx, w, h: scanlines_indexed8(idx, w, h))
open("palette_trns.png", "wb").write(b.build([frame0, frame1]))
PY

# ---------------------------------------------------------------------------
# 12: 16-bit RGBA. Each channel's high and low byte are deliberately
# different so STRIP_16 (truncate to the high byte) is distinguishable from
# rounding or taking the low byte.
# ---------------------------------------------------------------------------
python3 - <<'PY'
import sys
sys.path.insert(0, ".")
from apnglib import *

W = H = 2
b = ApngBuilder(W, H, bit_depth=16, color_type=COLOR_RGBA)
pixel16 = (0x1234, 0x5678, 0x9abc, 0xdef0)
frames = [
    frame(W, H, 0, 0, solid(W, H, pixel16), encode=scanlines_rgba16),
    frame(W, H, 0, 0, solid(W, H, (0x0102, 0x0304, 0x0506, 0xffff)), encode=scanlines_rgba16),
]
open("sixteen_bit.png", "wb").write(b.build(frames))
PY

# ---------------------------------------------------------------------------
# 13: truncated file. A syntactically-recognisable APNG (signature, IHDR,
# acTL, a leading fcTL) with NO IDAT at all — `read_until_image_data` hits
# EOF looking for the start of pixel data, which fails `probe`,
# `Animation::new` and `first_frame` alike with `Error::Malformed`.
# ---------------------------------------------------------------------------
python3 - <<'PY'
import sys
sys.path.insert(0, ".")
from apnglib import *

W = H = 4
out = bytearray()
out += PNG_SIGNATURE
out += ihdr(W, H, 8, COLOR_RGBA)
out += actl(1, 1)
out += fctl(0, W, H, 0, 0, 1, 10, DISPOSE_NONE, BLEND_SOURCE)
# Deliberately no IDAT/IEND: the stream ends mid-header-walk.
open("truncated.png", "wb").write(bytes(out))
PY

# ---------------------------------------------------------------------------
# 14: an IHDR claiming a canvas above richimg's default pixel cap
# (16384x16384), with only a zero-length IDAT (no real pixel data) — the
# central pixel-cap check in `Animation::new` must refuse this from `probe`'s
# reported dimensions alone, before any canvas allocation.
# ---------------------------------------------------------------------------
python3 - <<'PY'
import sys
sys.path.insert(0, ".")
from apnglib import *

SIDE = 16384  # 2x richimg's default 8192 cap per side
out = bytearray()
out += PNG_SIGNATURE
out += ihdr(SIDE, SIDE, 8, COLOR_RGBA)
out += actl(1, 1)
out += fctl(0, SIDE, SIDE, 0, 0, 1, 10, DISPOSE_NONE, BLEND_SOURCE)
out += chunk(b"IDAT", b"")  # empty: never read once TooLarge is raised from `probe`'s dimensions
out += iend()
open("oversized_canvas.png", "wb").write(bytes(out))
PY

# ---------------------------------------------------------------------------
# Reference frames: raw straight-alpha RGBA8, one file per composited frame,
# decoded by ffmpeg's own (independent) APNG decoder, which composites
# dispose/blend internally before the rawvideo mux.
#
# No `magick` cross-check: verified (2026, ImageMagick 7.1.1-27, Q16-HDRI)
# that this installed build's PNG delegate does not decode APNG animation
# AT ALL, not just the default-image case — `magick x.png -coalesce` on an
# ordinary multi-frame fixture (`fcTL` before `IDAT`, no default image)
# still yields exactly one output file, holding only the leading frame's
# pixels. `identify` likewise reports one frame (no `x.png[0]`/`x.png[1]`)
# for such a file. So "cross-checked … against magick if it reads APNG"
# does not apply here: it doesn't. ffmpeg is the sole independent reference.
# ---------------------------------------------------------------------------
write_refs_ffmpeg() {
    local png_file="$1"
    local stem="$2"
    local width height frame_count
    width=$(python3 -c "import struct,sys; d=open(sys.argv[1],'rb').read(); print(struct.unpack('>I', d[16:20])[0])" "$png_file")
    height=$(python3 -c "import struct,sys; d=open(sys.argv[1],'rb').read(); print(struct.unpack('>I', d[20:24])[0])" "$png_file")
    # `-vsync 0`: pass every decoded frame straight through with no
    # duplication/drop to match a target frame rate. ffmpeg's `apng` demuxer
    # otherwise reports an absurd derived `tbr` for small hand-built fcTL
    # delays, and the default rawvideo fps behaviour then duplicates each
    # frame thousands of times to fill the animation's total duration.
    ffmpeg -nostdin -y -v error -vsync 0 -i "$png_file" -f rawvideo -pix_fmt rgba "${stem}.raw" </dev/null
    local frame_bytes=$((width * height * 4))
    local total_bytes
    total_bytes=$(stat -c%s "${stem}.raw")
    frame_count=$((total_bytes / frame_bytes))
    local i=0
    while [ "$i" -lt "$frame_count" ]; do
        dd if="${stem}.raw" of="${REFS_DIR}/${stem}-${i}.rgba" bs="$frame_bytes" skip="$i" count=1 status=none
        i=$((i + 1))
    done
}

write_refs_ffmpeg dispose_none.png dispose_none
write_refs_ffmpeg dispose_background.png dispose_background
write_refs_ffmpeg dispose_previous.png dispose_previous
write_refs_ffmpeg dispose_previous_first_frame.png dispose_previous_first_frame
write_refs_ffmpeg blend_source.png blend_source
write_refs_ffmpeg blend_over.png blend_over
write_refs_ffmpeg still.png still
write_refs_ffmpeg fractional_delays.png fractional_delays
write_refs_ffmpeg short_delays.png short_delays
write_refs_ffmpeg loop_finite.png loop_finite
write_refs_ffmpeg default_image_not_a_frame.png default_image_not_a_frame
write_refs_ffmpeg palette_trns.png palette_trns
write_refs_ffmpeg sixteen_bit.png sixteen_bit

# ---------------------------------------------------------------------------
# Install the generated fixtures over the committed ones.
# ---------------------------------------------------------------------------
for name in dispose_none dispose_background dispose_previous dispose_previous_first_frame \
            blend_source blend_over still fractional_delays short_delays loop_finite loop_infinite \
            default_image_not_a_frame palette_trns sixteen_bit truncated oversized_canvas; do
    cp "$WORK/$name.png" "$FIXTURES_DIR/$name.png"
done

echo "make_apng.sh: fixtures and reference frames written to $FIXTURES_DIR"
